package ro.leo.visual;
import android.content.*;import android.app.*;import org.json.*;import java.util.*;
/** User-authored local rules. No network, calls, SMS, shell or microphone actions. */
final class AutomationRules {
 static final String[] EVENTS={"headset","power","wifi","bluetooth"};static final String[] ACTIONS={"music","night","normal","reminder"};
 static JSONArray read(Context c){try{return new JSONArray(c.getSharedPreferences("automation",0).getString("rules","[]"));}catch(Exception e){return new JSONArray();}}
 static boolean valid(String event,String action){return Arrays.asList(EVENTS).contains(event)&&Arrays.asList(ACTIONS).contains(action);}
 static synchronized void save(Context c,JSONArray rows)throws Exception{if(rows.length()>16)throw new IllegalArgumentException("Maximum 16 rules");HashSet<String> ids=new HashSet<String>();for(int n=0;n<rows.length();n++){JSONObject row=rows.getJSONObject(n);if(!valid(row.getString("event"),row.getString("action"))||!row.getString("id").matches("[A-Za-z0-9-]{1,50}")||!ids.add(row.getString("id")))throw new IllegalArgumentException();}c.getSharedPreferences("automation",0).edit().putString("rules",rows.toString()).commit();sync(c);}
 static boolean enabled(Context c){JSONArray rows=read(c);for(int n=0;n<rows.length();n++)if(rows.optJSONObject(n).optBoolean("enabled"))return true;return false;}
 static void sync(Context c){if(enabled(c))c.startForegroundService(new Intent(c,AutomationService.class));else c.stopService(new Intent(c,AutomationService.class));}
 static boolean due(long now,long last){return last<=0||now-last>=30000;}
 static void dispatch(Context c,String event){android.telecom.TelecomManager phone=(android.telecom.TelecomManager)c.getSystemService(Context.TELECOM_SERVICE);if(phone!=null&&phone.isInCall())return;JSONArray rows=read(c);SharedPreferences p=c.getSharedPreferences("automation",0);long now=System.currentTimeMillis();for(int n=0;n<rows.length();n++)try{JSONObject r=rows.getJSONObject(n);String id=r.getString("id"),action=r.getString("action");if(!r.optBoolean("enabled")||!event.equals(r.optString("event"))||!valid(event,action)||!due(now,p.getLong("last-"+id,0)))continue;p.edit().putLong("last-"+id,now).putString("last-result","Running: "+event+" → "+action).commit();if(action.equals("night")||action.equals("normal"))SoundProfiles.apply(c,action.equals("night")?3:0);else{NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("leo-rules","Leo automations",NotificationManager.IMPORTANCE_DEFAULT));Intent open=new Intent(c,action.equals("music")?MediaActivity.class:PremiumStudioActivity.class);PendingIntent intent=PendingIntent.getActivity(c,id.hashCode(),open,PendingIntent.FLAG_UPDATE_CURRENT);nm.notify(id.hashCode(),new Notification.Builder(c,"leo-rules").setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("Leo · "+event).setContentText(action.equals("music")?"Open Music":"Local reminder").setContentIntent(intent).setAutoCancel(true).build());}p.edit().putString("last-result","OK: "+event+" → "+action).apply();}catch(Exception e){p.edit().putString("last-result","Unavailable: "+event).apply();}}
}
